questionvariables.text:
cardn(S) := length(listify(S));
dset(S) := if emptyp(S) then "\\{\\,\\}" else sconcat("\\{", simplode(map(string, listify(S)), ", "), "\\}");
ix: 1+rand(10);
tf(k) := [[1, is(k=1), "True"], [2, is(k=2), "False"]];
/* Design: true or false for subset, superset and disjoint statements. Source: original. Essential only. Curated list, one seed per entry;
   traps A = B, D = {0}, D empty, D = {-5, 5}. Keys 1 true, 2 false; f: the other option for tests; e: explanations. */
L: [[{2,8},{2,8,10},{1,5},"\\{x : x \\text{ is a whole number}, x + 5 = 5\\}",1,2,1,1,2,1,2,2,"\\(A \\subset B\\) needs every element of \\(A\\) to be in \\(B\\), and \\(A \\neq B\\); here every element of \\(A\\) is in \\(B\\) and \\(A \\neq B\\), so \\(A \\subset B\\) is true.","\\(B \\supseteq C\\) means every element of \\(C\\) is in \\(B\\); here \\(1\\) and \\(5\\) are not in \\(B\\), so the statement is false.","\\(A \\cap C = \\{\\,\\}\\), so \\(A\\) and \\(C\\) have no element in common: they are disjoint.","\\(D = \\{0\\}\\) has \\(1\\) element; a singleton has exactly one element, so the statement is true."],
  [{1,5,9},{1,5,9},{5},"\\{x : x \\text{ is an even prime number}\\}",2,1,2,1,1,2,1,2,"\\(A \\subset B\\) needs every element of \\(A\\) to be in \\(B\\), and \\(A \\neq B\\); here \\(A = B\\), so \\(A\\) is not a proper subset of \\(B\\) and the statement is false.","\\(B \\supseteq C\\) means every element of \\(C\\) is in \\(B\\); here it is, so the statement is true.","\\(A \\cap C = \\{5\\}\\), so \\(A\\) and \\(C\\) have an element in common: they are not disjoint.","\\(D = \\{2\\}\\) has \\(1\\) element; a singleton has exactly one element, so the statement is true."],
  [{3,6},{3,6,9,15},{6,15},"\\{x : x \\text{ is a natural number}, x^2 = 16\\}",1,1,2,1,2,2,1,2,"\\(A \\subset B\\) needs every element of \\(A\\) to be in \\(B\\), and \\(A \\neq B\\); here every element of \\(A\\) is in \\(B\\) and \\(A \\neq B\\), so \\(A \\subset B\\) is true.","\\(B \\supseteq C\\) means every element of \\(C\\) is in \\(B\\); here it is, so the statement is true.","\\(A \\cap C = \\{6\\}\\), so \\(A\\) and \\(C\\) have an element in common: they are not disjoint.","\\(D = \\{4\\}\\) has \\(1\\) element; a singleton has exactly one element, so the statement is true."],
  [{7,8,9},{6,7,8},{1,2},"\\{x : x \\text{ is an integer}, x^2 = 25\\}",2,2,1,2,1,1,2,1,"\\(A \\subset B\\) needs every element of \\(A\\) to be in \\(B\\), and \\(A \\neq B\\); here \\(9\\) is not in \\(B\\), so the statement is false.","\\(B \\supseteq C\\) means every element of \\(C\\) is in \\(B\\); here \\(1\\) and \\(2\\) are not in \\(B\\), so the statement is false.","\\(A \\cap C = \\{\\,\\}\\), so \\(A\\) and \\(C\\) have no element in common: they are disjoint.","\\(D = \\{-5, 5\\}\\) has \\(2\\) elements; a singleton has exactly one element, so the statement is false."],
  [{10,20},{10,20,30},{30,40},"\\{x : x \\text{ is a natural number}, x + 4 = 4\\}",1,2,1,2,2,1,2,1,"\\(A \\subset B\\) needs every element of \\(A\\) to be in \\(B\\), and \\(A \\neq B\\); here every element of \\(A\\) is in \\(B\\) and \\(A \\neq B\\), so \\(A \\subset B\\) is true.","\\(B \\supseteq C\\) means every element of \\(C\\) is in \\(B\\); here \\(40\\) is not in \\(B\\), so the statement is false.","\\(A \\cap C = \\{\\,\\}\\), so \\(A\\) and \\(C\\) have no element in common: they are disjoint.","\\(D = \\{\\,\\}\\) has \\(0\\) elements; a singleton has exactly one element, so the statement is false."],
  [{0,1},{0,1,2},{2},"\\{x : x \\text{ is a whole number}, 3x = 0\\}",1,1,1,1,2,2,2,2,"\\(A \\subset B\\) needs every element of \\(A\\) to be in \\(B\\), and \\(A \\neq B\\); here every element of \\(A\\) is in \\(B\\) and \\(A \\neq B\\), so \\(A \\subset B\\) is true.","\\(B \\supseteq C\\) means every element of \\(C\\) is in \\(B\\); here it is, so the statement is true.","\\(A \\cap C = \\{\\,\\}\\), so \\(A\\) and \\(C\\) have no element in common: they are disjoint.","\\(D = \\{0\\}\\) has \\(1\\) element; a singleton has exactly one element, so the statement is true."],
  [{4,5,6},{4,5,6},{1,4},"\\{x : x \\text{ is a prime number between 13 and 19}\\}",2,2,2,1,1,1,1,2,"\\(A \\subset B\\) needs every element of \\(A\\) to be in \\(B\\), and \\(A \\neq B\\); here \\(A = B\\), so \\(A\\) is not a proper subset of \\(B\\) and the statement is false.","\\(B \\supseteq C\\) means every element of \\(C\\) is in \\(B\\); here \\(1\\) is not in \\(B\\), so the statement is false.","\\(A \\cap C = \\{4\\}\\), so \\(A\\) and \\(C\\) have an element in common: they are not disjoint.","\\(D = \\{17\\}\\) has \\(1\\) element; a singleton has exactly one element, so the statement is true."],
  [{11,13},{11,12,13,14},{12,14},"\\{x : x \\text{ is a square number between 10 and 30}\\}",1,1,1,2,2,2,2,1,"\\(A \\subset B\\) needs every element of \\(A\\) to be in \\(B\\), and \\(A \\neq B\\); here every element of \\(A\\) is in \\(B\\) and \\(A \\neq B\\), so \\(A \\subset B\\) is true.","\\(B \\supseteq C\\) means every element of \\(C\\) is in \\(B\\); here it is, so the statement is true.","\\(A \\cap C = \\{\\,\\}\\), so \\(A\\) and \\(C\\) have no element in common: they are disjoint.","\\(D = \\{16, 25\\}\\) has \\(2\\) elements; a singleton has exactly one element, so the statement is false."],
  [{2,3,7},{2,3},{3},"\\{x : x \\text{ is a whole number}, x < 1\\}",2,1,2,1,1,2,1,2,"\\(A \\subset B\\) needs every element of \\(A\\) to be in \\(B\\), and \\(A \\neq B\\); here \\(7\\) is not in \\(B\\), so the statement is false.","\\(B \\supseteq C\\) means every element of \\(C\\) is in \\(B\\); here it is, so the statement is true.","\\(A \\cap C = \\{3\\}\\), so \\(A\\) and \\(C\\) have an element in common: they are not disjoint.","\\(D = \\{0\\}\\) has \\(1\\) element; a singleton has exactly one element, so the statement is true."],
  [{6,9},{3,6,9},{1,2,3},"\\{x : x \\text{ is a natural number}, x < 3\\}",1,2,1,2,2,1,2,1,"\\(A \\subset B\\) needs every element of \\(A\\) to be in \\(B\\), and \\(A \\neq B\\); here every element of \\(A\\) is in \\(B\\) and \\(A \\neq B\\), so \\(A \\subset B\\) is true.","\\(B \\supseteq C\\) means every element of \\(C\\) is in \\(B\\); here \\(1\\) and \\(2\\) are not in \\(B\\), so the statement is false.","\\(A \\cap C = \\{\\,\\}\\), so \\(A\\) and \\(C\\) have no element in common: they are disjoint.","\\(D = \\{1, 2\\}\\) has \\(2\\) elements; a singleton has exactly one element, so the statement is false."]];
A: L[ix][1]; B: L[ix][2]; C: L[ix][3]; Dd: L[ix][4]; k1: L[ix][5]; k2: L[ix][6]; k3: L[ix][7]; k4: L[ix][8]; f1: L[ix][9]; f2: L[ix][10]; f3: L[ix][11]; f4: L[ix][12]; e1: L[ix][13]; e2: L[ix][14]; e3: L[ix][15]; e4: L[ix][16]; 
